#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Release gate staging measurements (spec §14 step 11). Run from the repo root: bash scripts/release-gate.sh
# Staging only, never production. It seeds 2,000 fake Devices on staging, measures, then deletes them again.
TOTAL_STAGES=9
cd "$(dirname "$0")/.."   # every path below is relative to the repo root
mkdir -p .scratch
ENV_FILE=".scratch/release-gate.env"        # the staging account id, URL and the throwaway probe Cloud Code
RESULTS=".scratch/release-gate-results.md"  # what you measured; hand it back to the session
SAVE_B64=".scratch/release-gate-save.b64"
WRANGLER=(npx wrangler --config worker/wrangler.toml)
SEED_DEVICES=2000

# record "what" "value" appends one measured line to the results file.
record() { printf -- '- %s: %s\n' "$1" "$2" >> "$RESULTS"; printf '  %s✓ recorded%s %s: %s\n' "$GREEN" "$RESET" "$1" "$2"; }
# masked CODE shows only the last group of a Cloud Code.
masked() { printf 'WBLY-••••-••••-••••-%s' "${1: -4}"; }
# api METHOD PATH [curl args…] calls staging as the probe; the Cloud Code goes in through a header file, never argv.
api() {
  local method="$1" path="$2"; shift 2
  curl -sS -X "$method" -H @<(printf 'Authorization: Bearer %s\n' "$PROBE_CODE") "$@" "$STAGING_API_URL$path"
}
# d1 DB ARGS… runs wrangler d1 execute against a STAGING database.
d1() { local db="$1"; shift; CLOUDFLARE_ACCOUNT_ID="$STAGING_ACCOUNT_ID" "${WRANGLER[@]}" d1 execute "$db" --remote --env staging "$@"; }

banner "Wobbly Mart · release gate (staging)"

stage "Staging account and URL"
warn "Everything here runs against STAGING. Never point it at production."
ask STAGING_ACCOUNT_ID "The staging Cloudflare account ID (in .scratch/worker-setup.env or the dashboard):"
write_env STAGING_ACCOUNT_ID "$STAGING_ACCOUNT_ID"
url=$(gh variable get VITE_API_URL_STAGING 2>/dev/null || true)
[[ -n "$url" ]] && note "GitHub variable VITE_API_URL_STAGING = $url"
ask STAGING_API_URL "The staging Worker URL (https://wobbly-mart-api-staging.<sub>.workers.dev):"
[[ "$STAGING_API_URL" == *staging* ]] || { warn "That URL doesn't say staging. Stopping."; exit 1; }
write_env STAGING_API_URL "${STAGING_API_URL%/}"
say "Wrangler must be logged in to the STAGING account."
if confirm "Log Wrangler in now (opens the browser)?"; then npx wrangler login; fi
read -r DAY SIM_VERSION < <(npx tsx --eval "import { dailyDay } from './src/sim/daily'; import { SIM_VERSION } from './src/sim/version'; console.log(dailyDay(Date.now()), SIM_VERSION)")
printf '# Release gate results, %s UTC\n\nDaily day %s, SIM_VERSION %s, %s seeded Devices.\n\n' \
  "$(date -u '+%Y-%m-%d %H:%M')" "$DAY" "$SIM_VERSION" "$SEED_DEVICES" > "$RESULTS"

stage "A probe Device and 2,000 seeded Devices"
say "Creates one Device ('Gate Probe') through the API, then seeds $SEED_DEVICES fake Devices straight into"
say "staging's wobbly_board: a Corner Shop Score and Speed row, today's Daily row and a Streak each."
note "About $((SEED_DEVICES * 4)) row writes, well inside the free 100K a day. Stage 9 deletes them all."
confirm "Create the probe and seed staging now?" || { warn "Nothing seeded. Stopping."; exit 1; }
res=$(curl -sS -X POST -H 'Content-Type: application/json' --data '{"nickname":"Gate Probe"}' "$STAGING_API_URL/v1/device")
PROBE_CODE=$(printf '%s' "$res" | sed -n 's/.*"cloudCode":"\([^"]*\)".*/\1/p')
[[ -n "$PROBE_CODE" ]] || { warn "POST /v1/device failed: $res"; exit 1; }
write_env PROBE_CODE "$PROBE_CODE"
say "Probe Cloud Code $(masked "$PROBE_CODE") (kept in $ENV_FILE, mode 600)."
# the Worker stores SHA-256 of the 16 code characters (no WBLY, no dashes)
flat=$(printf '%s' "$PROBE_CODE" | tr -d '-'); hash=$(printf '%s' "${flat#WBLY}" | sha256sum | cut -c1-64)
seed=".scratch/release-gate-seed.sql"
{
  printf 'WITH RECURSIVE n(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM n WHERE i < %s)\n' "$SEED_DEVICES"
  printf 'INSERT INTO `device` (`token_hash`, `nickname`, `streak_current`, `streak_best`, `streak_last_day`, `created_at`, `last_seen_at`)\n'
  printf "SELECT randomblob(32), 'Seed ' || i, i %% 7, 1 + i %% 90, %s, unixepoch(), unixepoch() FROM n;\n" "$DAY"
  printf 'INSERT INTO `board_entry` (`kind`, `map`, `day`, `sim_version`, `id_device`, `score`, `play_time`, `updated_at`)\n'
  printf "SELECT 'score', 'corner-shop', 0, %s, \`id_device\`, (\`id_device\` * 7919) %% 100000, 3600, unixepoch() FROM \`device\` WHERE \`nickname\` LIKE 'Seed %%';\n" "$SIM_VERSION"
  printf 'INSERT INTO `board_entry` (`kind`, `map`, `day`, `sim_version`, `id_device`, `ticks`, `updated_at`)\n'
  printf "SELECT 'speed', 'corner-shop', 0, %s, \`id_device\`, 60000 + (\`id_device\` * 7919) %% 60000, unixepoch() FROM \`device\` WHERE \`nickname\` LIKE 'Seed %%';\n" "$SIM_VERSION"
  printf 'INSERT INTO `board_entry` (`kind`, `map`, `day`, `sim_version`, `id_device`, `ticks`, `score`, `money`, `updated_at`)\n'
  printf "SELECT 'daily', 'daily', %s, %s, \`id_device\`, 20000 + (\`id_device\` * 7919) %% 30000, 500, 500, unixepoch() FROM \`device\` WHERE \`nickname\` LIKE 'Seed %%';\n" "$DAY" "$SIM_VERSION"
  # the probe sits mid-Board on all four, so its reads pay for Around you and its rank
  printf 'INSERT INTO `board_entry` (`kind`, `map`, `day`, `sim_version`, `id_device`, `score`, `ticks`, `play_time`, `updated_at`)\n'
  printf 'SELECT k.kind, k.map, k.day, %s, d.`id_device`, 50000, k.ticks, 3600, unixepoch() FROM `device` d,\n' "$SIM_VERSION"
  printf "(SELECT 'score' AS kind, 'corner-shop' AS map, 0 AS day, NULL AS ticks UNION ALL SELECT 'speed', 'corner-shop', 0, 90000 UNION ALL SELECT 'daily', 'daily', %s, 35000) k\n" "$DAY"
  printf "WHERE d.\`token_hash\` = X'%s';\n" "$hash"
  printf "UPDATE \`device\` SET \`streak_current\` = 3, \`streak_best\` = 45, \`streak_last_day\` = %s WHERE \`token_hash\` = X'%s';\n" "$DAY" "$hash"
} > "$seed"
d1 wobbly_board --file "$seed"
rm -f "$seed"

stage "rows_read per Wall tab"
say "Reads each of the four Boards once as the probe: what a Wall tab costs with a Device mid-Board."
for path in "/v1/boards/score/corner-shop" "/v1/boards/speed/corner-shop" "/v1/boards/daily/daily?day=$DAY" "/v1/boards/streak/-"; do
  out=$(api GET "$path" -w '\n%{http_code}')
  code=$(printf '%s' "$out" | tail -n1); total=$(printf '%s' "$out" | sed -n 's/.*"total":\([0-9]*\).*/\1/p')
  record "GET $path" "HTTP $code, total ${total:-?}"
done
say "D1 Insights lags a few minutes behind."
pause "Wait about 3 minutes, then press Enter to fetch Insights."
if CLOUDFLARE_ACCOUNT_ID="$STAGING_ACCOUNT_ID" "${WRANGLER[@]}" d1 insights wobbly_board --env staging \
  --time-period 1h --sort-by reads --limit 25 --json > .scratch/release-gate-insights.json; then
  record "D1 Insights" ".scratch/release-gate-insights.json"
else
  warn "Insights failed; Dashboard → D1 → wobbly_board → Metrics shows rows read too."
  ask READS_NOTE "Rows read you saw there (Enter to skip):" || true
  [[ -n "${READS_NOTE:-}" ]] && record "Rows read (dashboard)" "$READS_NOTE"
fi

stage "The largest cloud save: size and CPU"
say "The bot plays every Map to 100% and writes that save (the biggest a player can have). Takes a few minutes."
BOT_SAVE_OUT="$SAVE_B64" npm run --silent bot > /dev/null || warn "the bot run failed; using whatever it wrote"
[[ -s "$SAVE_B64" ]] || { warn "No save written. Stopping."; exit 1; }
record "Full-progress save" "$(wc -c < "$SAVE_B64" | tr -d ' ') B base64"
code=$(printf '{"saveCode":"%s"}' "$(cat "$SAVE_B64")" | api PUT /v1/save -H 'Content-Type: application/json' --data-binary @- -o /dev/null -w '%{http_code}')
record "PUT /v1/save (largest)" "HTTP $code (expect 204)"
code=$(api GET /v1/save -o /dev/null -w '%{http_code}')
record "GET /v1/save" "HTTP $code (expect 200)"
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "wobbly-mart-api-staging → Observability (Logs) → the newest PUT /v1/save invocation."
step "Read its CPU time (\$workers.cpuTimeMs). Free allows 10 ms; it includes gunzip + parseSave (decodeSaveCode)."
ask SAVE_CPU_MS "CPU time of that PUT /v1/save, in ms:"
record "PUT /v1/save CPU" "$SAVE_CPU_MS ms"
ask READ_CPU_MS "While there: the highest CPU time of the four GET /v1/boards calls, in ms (Enter to skip):" || true
[[ -n "${READ_CPU_MS:-}" ]] && record "GET /v1/boards CPU (max)" "$READ_CPU_MS ms"

stage "Logs carry no Cloud Code"
say "Same Logs view. Open the PUT /v1/save entry and expand the request."
step "Check there is no Authorization header and no Cloud Code ($(masked "$PROBE_CODE"))."
step "Also search the logs for: WBLY"
if confirm "No Authorization header and no WBLY code anywhere in the logs?"; then record "Logs free of Cloud Codes" "yes"
else record "Logs free of Cloud Codes" "NO (blocker)"; fi

stage "Rate limits on Free: a scripted burst"
say "Waits 60 s so the earlier calls don't count, then fires 40 Board reads and 4 Device creates from this IP."
note "Expect about 30 × 200 then 429 for reads (limit 30/60 s), and 3 × 200 then 429 for creates (3/60 s)."
note "The binding counts per Cloudflare location and is approximate, so a few over is fine."
pause "Press Enter to start (takes about a minute)."
sleep 60
reads=$(for _ in $(seq 40); do curl -s -o /dev/null -w '%{http_code}\n' "$STAGING_API_URL/v1/boards/score/corner-shop"; done | sort | uniq -c | awk '{printf "%s×%s ", $1, $2}')
record "Read burst (40)" "$reads"
creates=$(for _ in 1 2 3 4; do curl -s -o /dev/null -w '%{http_code}\n' -X POST -H 'Content-Type: application/json' --data '{"nickname":"Gate Burst"}' "$STAGING_API_URL/v1/device"; done | tr '\n' ' ')
record "Device create burst (4)" "$creates"

stage "The nightly cron"
open_url "https://dash.cloudflare.com/?to=/:account/workers-and-pages"
step "wobbly-mart-api-staging → Settings → Triggers: Cron Triggers shows 30 0 * * *."
step "Observability (Logs): filter on the scheduled event; the latest 00:30 UTC run shows Ok, no error."
if confirm "Cron is 30 0 * * * and the last 00:30 UTC run succeeded?"; then record "Cron" "30 0 * * *, last run ok"
else ask CRON_NOTE "What did you see?"; record "Cron" "NOT ok: $CRON_NOTE"; fi

stage "Delete my Device on staging"
code=$(api DELETE /v1/device -o /dev/null -w '%{http_code}')
record "DELETE /v1/device" "HTTP $code (expect 204)"
code=$(api GET /v1/device -o /dev/null -w '%{http_code}')
record "GET /v1/device after Delete" "HTTP $code (expect 401)"
code=$(api GET /v1/save -o /dev/null -w '%{http_code}')
record "GET /v1/save after Delete" "HTTP $code (expect 401)"

stage "Clean up the seeded rows"
say "Deletes the 'Seed …' and 'Gate Burst' Devices and their Board rows from staging's wobbly_board."
if confirm "Delete them now?"; then
  d1 wobbly_board --command "DELETE FROM \`board_entry\` WHERE \`id_device\` IN (SELECT \`id_device\` FROM \`device\` WHERE \`nickname\` LIKE 'Seed %' OR \`nickname\` = 'Gate Burst'); DELETE FROM \`device\` WHERE \`nickname\` LIKE 'Seed %' OR \`nickname\` = 'Gate Burst';"
  left=$(d1 wobbly_board --json --command "SELECT COUNT(*) AS n FROM \`device\` WHERE \`nickname\` LIKE 'Seed %' OR \`nickname\` IN ('Gate Burst', 'Gate Probe')" | sed -n 's/.*"n": *\([0-9]*\).*/\1/p')
  record "Seed rows left" "${left:-?} (expect 0)"
else
  SKIPPED+=("seed clean-up: re-run the wizard's last stage, or run its DELETE by hand on staging")
fi
rm -f "$SAVE_B64"
write_env PROBE_CODE ""

finish
say "Results: $RESULTS (and .scratch/release-gate-insights.json). Hand both back to the session."
say "After the release merge: open https://seif-sallam.github.io/Wobbly-Mart/privacy.html and check it loads."
}

run_wizard "$@"; exit
